jsonLd:
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": "https://2ndmarket.fr/#website",
      "url": "https://2ndmarket.fr",
      "name": "2nd Market",
      "publisher": { "@id": "https://2ndmarket.fr/#organization" },
      "potentialAction": {
        "@type": "SearchAction",
        "target": {
          "@type": "EntryPoint",
          "urlTemplate": "https://app.2ndmarket.fr/scpi?q={search_term_string}"
        },
        "query-input": "required name=search_term_string"
      }
    },
    {
      "@type": "WebPage",
      "@id": "https://2ndmarket.fr/#webpage",
      "url": "https://2ndmarket.fr",
      "name": "SCPI à décote : achetez ou revendez entre particuliers | 2nd Market",
      "description": "Vendez vos parts SCPI en 4-8 semaines ou achetez avec décote 20-35 %. Marché secondaire gré à gré. Transaction notaire. Finance Innovation.",
      "isPartOf": { "@id": "https://2ndmarket.fr/#website" },
      "about": { "@id": "https://2ndmarket.fr/#organization" },
      "speakable": {
        "@type": "SpeakableSpecification",
        "cssSelector": [".home-header-heading", ".home-about-description", ".home-buyer-description", ".faq-question", ".faq-answer"]
      }
    },
    {
      "@type": "FAQPage",
      "@id": "https://2ndmarket.fr/#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Comment se déroule une vente ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Le processus se déroule en 5 étapes : publication de l'annonce, réception des offres, signature de l'avant-contrat, vérifications notariales, finalisation. Délai total moyen : 4 à 8 semaines après acceptation de l'offre."
          }
        },
        {
          "@type": "Question",
          "name": "Dois-je repayer les 12 % de frais de souscription sur 2nd Market ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Non. Ces frais ne concernent que l'achat de parts neuves. Sur 2nd Market, vous rachetez des parts existantes : personne ne les repaye. Pour l'acheteur, c'est une économie directe de 8 à 12 %, en plus des décotes souvent observées."
          }
        },
        {
          "@type": "Question",
          "name": "2nd Market est-elle indépendante ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Oui. 2nd Market n'est ni société de gestion, ni CGP, ni CIF. Nous ne percevons aucune rétrocommission des sociétés de gestion. 2nd Market est membre du label Finance Innovation et accompagnée par DLA Piper."
          }
        },
        {
          "@type": "Question",
          "name": "Pourquoi passer par un notaire ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Le notaire vérifie identités et solvabilité, contrôle l'origine des fonds, et séquestre l'argent jusqu'au transfert effectif des parts. Les fonds ne sont libérés qu'après toutes les vérifications légales."
          }
        },
        {
          "@type": "Question",
          "name": "Quel est le délai moyen pour vendre des parts SCPI ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "2 à 6 semaines pour recevoir une offre, 4 à 8 semaines pour finaliser la transaction. Le délai moyen de retrait via les sociétés de gestion dépasse 600 jours en 2025."
          }
        },
        {
          "@type": "Question",
          "name": "Quels sont les frais sur 2nd Market ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Publication et offres sont gratuites. Vendeur : commission dégressive de 6 % à 0,75 % TTC + frais de notaire dégressifs (540 € minimum). Acheteur : 1,8 % TTC + 240 € d'avant-contrat + frais société de gestion (0-200 €). Droits d'enregistrement : 5 % du prix (article 726 CGI), dus sur toute cession de SCPI sur le marché secondaire."
          }
        }
      ]
    }
  ]
}
